SELECT q.id AS "Событие №",q.occurred_at AT TIME ZONE 'Asia/Irkutsk' AS "Дата",CASE q.kind WHEN 'created' THEN 'Создана' WHEN 'claimed' THEN 'Взята в работу' WHEN 'reassigned' THEN 'Сменён исполнитель' WHEN 'transferred' THEN 'Передана' WHEN 'reopened' THEN 'Повторно открыта' WHEN 'status_changed' THEN 'Изменён статус' WHEN 'closed' THEN 'Закрыта' WHEN 'cancelled' THEN 'Отменена' WHEN 'message_delivered' THEN 'Доставка сообщения' WHEN 'message' THEN 'Сообщение' WHEN 'first_response' THEN 'Первый ответ' ELSE q.kind END AS "Событие",coalesce(u.name,CASE WHEN q.actor_id=t.client_id THEN nullif(t.client_name,'') WHEN q.actor_id IS NOT NULL THEN 'Участник #'||q.actor_id ELSE 'Нет данных' END) AS "Автор",d.name AS "Отдел",f.name AS "Откуда",dest.name AS "Куда",a.name AS "Назначенный",q.status AS "Статус",q.cycle_number AS "Цикл",q.detail AS "Описание",q.incomplete AS "Неполные сведения"
FROM analytics.events q JOIN analytics.tickets t ON t.id=q.ticket_id LEFT JOIN analytics.employees u ON u.id=q.actor_id LEFT JOIN analytics.employees a ON a.id=q.assignee_id LEFT JOIN analytics.departments d ON d.code=q.department LEFT JOIN analytics.departments f ON f.code=q.from_department LEFT JOIN analytics.departments dest ON dest.code=q.to_department WHERE q.ticket_id={{ticket_id}} ORDER BY q.occurred_at,q.id
